function validate([word1, word2]) {
  if (word1.length < 1 || word2.length < 1) return 'Both words need at least one character.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Use only lowercase English letters.';
  return null;
}

