function isItPossible(word1, word2) {
  const count1 = new Array(26).fill(0);
  const count2 = new Array(26).fill(0);
  for (const ch of word1) {
    count1[ch.charCodeAt(0) - 97]++;
  }
  for (const ch of word2) {
    count2[ch.charCodeAt(0) - 97]++;
  }
  const distinct = (count) => count.filter((c) => c > 0).length;
  for (let a = 0; a < 26; a++) {
    if (count1[a] === 0) continue;
    for (let b = 0; b < 26; b++) {
      if (count2[b] === 0) continue;
      count1[a]--;
      count1[b]++;
      count2[b]--;
      count2[a]++;
      const equal = distinct(count1) === distinct(count2);
      count1[a]++;
      count1[b]--;
      count2[b]++;
      count2[a]--;
      if (equal) {
        return true;
      }
    }
  }
  return false;
}

