function isItPossible(word1, word2) {
  for (let i = 0; i < word1.length; i++) {
    for (let j = 0; j < word2.length; j++) {
      const next1 = word1.slice(0, i) + word2[j] + word1.slice(i + 1);
      const next2 = word2.slice(0, j) + word1[i] + word2.slice(j + 1);
      if (new Set(next1).size === new Set(next2).size) return true;
    }
  }
  return false;
}

