function generate(rand, size) {
  const word = (length, alphabet, offset) => {
    let text = '';
    for (let i = 0; i < length; i++) text += String.fromCharCode(97 + (offset + Math.floor(rand() * alphabet)) % 26);
    return text;
  };
  if (size === 'large') {
    const length1 = 5000 + Math.floor(rand() * 5001);
    const length2 = 5000 + Math.floor(rand() * 5001);
    const alphabet1 = 1 + Math.floor(rand() * 26);
    const alphabet2 = 1 + Math.floor(rand() * 26);
    return [word(length1, alphabet1, Math.floor(rand() * 26)), word(length2, alphabet2, Math.floor(rand() * 26))];
  }
  const length1 = 1 + Math.floor(rand() * 6);
  const length2 = 1 + Math.floor(rand() * 6);
  const alphabet1 = 1 + Math.floor(rand() * 5);
  const alphabet2 = 1 + Math.floor(rand() * 5);
  return [word(length1, alphabet1, Math.floor(rand() * 4)), word(length2, alphabet2, Math.floor(rand() * 4))];
}
